def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    my_def = my.count('D')
    opp_def = opp.count('D')

    # Defect against highly defective opponents
    if n >= 5 and opp_def >= n - 2:
        return 'D'
    if n >= 10 and opp_def * 2 > n:
        return 'D'

    last_my = my[-1]
    last_opp = opp[-1]

    if last_opp == 'D':
        # Endgame: don't forgive defections in last 5 rounds
        if n >= 95:
            return 'D'
        # Forgive rare defections
        if opp_def <= max(1, n // 10):
            return 'C'
        if last_my == 'D' and opp_def <= n // 2:
            return 'C'
        return 'D'

    # Opponent cooperated last round.
    # Late probe at n=90
    if n == 90 and last_opp == 'C':
        return 'D'

    # If we have never defected, consider early probes.
    if my_def == 0:
        if opp_def == 0 and n in (20, 40, 60, 80):
            return 'D'
        return 'C'

    # We have defected before. Check the response to our last defection.
    # Find the most recent defection by us that has a known response.
    i = -1
    for j in range(n - 2, -1, -1):
        if my[j] == 'D':
            i = j
            break
    if i != -1:
        if opp[i + 1] == 'C':
            # They forgave our defection. Continue exploiting.
            return 'D'
        else:
            # They retaliated. Resume cooperation.
            return 'C'
    else:
        # Our only defection was the last action, and opponent cooperated.
        # Cooperate next to test.
        return 'C'
